package com.fin.wallet.mapper;

import com.fin.wallet.dto.ExpenseDTO;
import com.fin.wallet.entity.Expense;
import org.mapstruct.BeanMapping;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;
import org.mapstruct.MappingTarget;
import org.mapstruct.NullValuePropertyMappingStrategy;

// Implementation is generated by MapStruct at compile time (target/generated-sources)
@Mapper(componentModel = MappingConstants.ComponentModel.SPRING)
public interface ExpenseMapper extends EntityMapper<ExpenseDTO, Expense> {

	@Override
	@Mapping(target = "userId", source = "user.id")
	ExpenseDTO toDto(Expense expense);

	// id, timestamps and user are managed by the server, never copied from the DTO
	@Override
	@Mapping(target = "id", ignore = true)
	@Mapping(target = "user", ignore = true)
	@Mapping(target = "createdAt", ignore = true)
	@Mapping(target = "updatedAt", ignore = true)
	Expense toEntity(ExpenseDTO dto);

	@Override
	@Mapping(target = "id", ignore = true)
	@Mapping(target = "user", ignore = true)
	@Mapping(target = "createdAt", ignore = true)
	@Mapping(target = "updatedAt", ignore = true)
	void update(@MappingTarget Expense expense, ExpenseDTO dto);

	@Override
	@BeanMapping(nullValuePropertyMappingStrategy = NullValuePropertyMappingStrategy.IGNORE)
	@Mapping(target = "id", ignore = true)
	@Mapping(target = "user", ignore = true)
	@Mapping(target = "createdAt", ignore = true)
	@Mapping(target = "updatedAt", ignore = true)
	void partialUpdate(@MappingTarget Expense expense, ExpenseDTO dto);

}
